const body = $input.item.json.body || $input.item.json;

// Extract message data from WhatsApp webhook payload
const entry = body.entry?.[0];
const changes = entry?.changes?.[0];
const value = changes?.value;
const message = value?.messages?.[0];

if (!message) {
  return [{ json: { skip: true } }];
}

const telefono = message.from;
const texto = message.text?.body || '';
const messageId = message.id;
const timestamp = message.timestamp;
const nombreContacto = value?.contacts?.[0]?.profile?.name || '';

return [{
  json: {
    telefono,
    texto,
    messageId,
    timestamp,
    nombreContacto,
    skip: false
  }
}];

const msgData = $('🔧 Extraer Mensaje y Teléfono').item.json;
const empresaRaw = $('🏢 Obtener Empresa G54').item.json;
const waConfigRaw = $('⚙️ Obtener WA Config G54').item.json;
const leadRaw = $('📋 Buscar Lead Existente').item.json;
const productosRaw = $('📦 Obtener Productos G54').item.json;

// G54 field mapping
const empresa = empresaRaw.data || empresaRaw || {};
const waConfig = waConfigRaw?.data || {};

// Agent identity — configurable desde G54 WA Config (campo agent_name)
const nombre_agente = waConfig.agent_name || 'Alex';

// Company data (G54 field names)
const empresa_nombre = empresa.name || 'Crating Express';
const empresa_descripcion = empresa.description || '';
const empresa_ciudad = empresa.base_city || 'Miami, FL';
const empresa_web = empresa.website || '';
const emailVendedor = (empresa.emails || []).join(',') || 'risosadmi@gmail.com';

// WA Config — desde G54, fallback a defaults hasta que el endpoint exista
const bienvenida = waConfig.welcome_message
  || `Hola 👋 gracias por contactarnos. Soy ${nombre_agente}, el asistente de ${empresa_nombre}. ¿En qué te puedo ayudar?`;
const instruccionesIA = waConfig.ia_instructions || '';
const promptTemplate = waConfig.system_prompt || '';
const followup24 = waConfig.followup_24h || '';
const followup72 = waConfig.followup_72h || '';

// Products catalog desde G54
const productos = productosRaw.data || [];
const catalogoProductos = productos.map(p => {
  const nombre = p.name || '';
  const desc = p.description || '';
  const kw = (p.keywords || []).join(', ');
  return `• ${nombre}: ${desc}${kw ? ' [' + kw + ']' : ''}`;
}).filter(l => l.length > 3).join('\n');

// Lead data — formato G54: { data: [{ id, phone, name, estado, historial, datos, clasificacion, cotizacion_enviada }] }
const leads = leadRaw?.data || [];
const leadExistente = leads[0] || null;
const leadId = leadExistente?.id || null;
const leadDatos = leadExistente?.datos || {};
const estado = leadExistente?.estado || 'Nuevo';
const historial = leadExistente?.historial || '';
const esNuevo = !leadId;
const cotizacionEnviada = leadExistente?.cotizacion_enviada === true || ['Lead Caliente','Cotizacion_Enviada','Calificado'].includes(estado);

let datosRecolectados = {
  nombre_cliente: leadDatos.nombre_cliente || leadExistente?.name || null,
  producto: leadDatos.producto || null,
  medidas: leadDatos.medidas || null,
  fecha: leadDatos.fecha || null,
  tipo_cajon: leadDatos.tipo_cajon || null,
  proteccion_extra: leadDatos.proteccion_extra !== undefined ? leadDatos.proteccion_extra : null,
  direccion: leadDatos.direccion || null,
  correo_contacto: leadDatos.correo_contacto || null
};

// Build prompt — soporta {{AGENTE}} {{EMPRESA}} {{CATALOGO}} {{INSTRUCCIONES}}
const promptSistema = promptTemplate
  .replace(/\{\{AGENTE\}\}/g, nombre_agente)
  .replace(/\{\{EMPRESA\}\}/g, empresa_nombre)
  .replace(/\{\{CATALOGO\}\}/g, catalogoProductos)
  .replace(/\{\{INSTRUCCIONES\}\}/g, instruccionesIA ? 'Instrucciones adicionales: ' + instruccionesIA : '')
  .trim();

// Saludo hora Miami (UTC-4)
const horaMiami = (new Date().getUTCHours() - 4 + 24) % 24;
const saludoHora = horaMiami >= 6 && horaMiami < 12 ? 'buenos días'
  : horaMiami >= 12 && horaMiami < 19 ? 'buenas tardes'
  : 'buenas noches';

const cleanCheck = v => (!v || v === 'desconocido' || v === 'null' || v === 'undefined') ? null : v;
const dR = datosRecolectados;
let proximoPaso;
if (cotizacionEnviada)             proximoPaso = 'POST_COTIZACION';
else if (esNuevo)                  proximoPaso = 'PRIMER_CONTACTO';
else if (!cleanCheck(dR.nombre_cliente)) proximoPaso = 'PEDIR_NOMBRE';
else if (!cleanCheck(dR.producto))       proximoPaso = 'PEDIR_PRODUCTO';
else if (!cleanCheck(dR.medidas))        proximoPaso = 'PEDIR_MEDIDAS';
else if (!cleanCheck(dR.tipo_cajon))     proximoPaso = 'PEDIR_TIPO_CAJON';
else if (dR.proteccion_extra === null || dR.proteccion_extra === undefined || dR.proteccion_extra === 'desconocido')
                                   proximoPaso = 'PEDIR_PROTECCION';
else                               proximoPaso = 'LISTO_PARA_COTIZAR';

return [{ json: {
  telefono: msgData.telefono,
  texto: msgData.texto,
  nombreContacto: msgData.nombreContacto || '',
  emailVendedor,
  nombre_agente,
  empresa_nombre,
  empresa_descripcion,
  empresa_ciudad,
  instruccionesIA,
  bienvenida,
  followup24,
  followup72,
  leadId,
  estado,
  historial,
  datosRecolectados,
  cotizacionEnviada,
  esNuevo,
  saludoHora,
  catalogoProductos,
  promptSistema,
  proximoPaso
} }];

const data = $input.item.json;
const leads = data.data || data.records || [];
const now = new Date();
const results = [];

for (const lead of leads) {
  const ultimaActividad = new Date(lead.ultima_actividad || lead.fields?.Ultima_Actividad || lead.fields?.Ultima_Interaccion);
  const horasDiff = (now - ultimaActividad) / (1000 * 60 * 60);
  let tipoFollowup = null;
  if (horasDiff >= 72)      tipoFollowup = '72h';
  else if (horasDiff >= 24) tipoFollowup = '24h';
  if (tipoFollowup) {
    results.push({ json: {
      leadId: lead.id || lead.fields?.id || lead.id,
      telefono: (lead.phone || lead.fields?.Telefono || '').replace(/^\+/,''),
      nombre: lead.name || lead.fields?.Nombre || '',
      tipoFollowup,
      estado: lead.estado || lead.fields?.Estado || ''
    }});
  }
}
return results;

