// Handle OpenAI-format (Groq/DeepSeek choices) or Contingency (direct object)
const raw = $input.item.json;
let aiResponse;
if (raw._contingencia) {
  aiResponse = JSON.stringify(raw);
} else {
  aiResponse = raw.choices?.[0]?.message?.content || '{}';
}

let result;
try { result = JSON.parse(aiResponse); }
catch(e) {
  result = {
    mensaje: 'Gracias por tu mensaje. Te ayudaremos con tu cotización.',
    datos_actualizados: {},
    dimensiones: { largo: null, ancho: null, alto: null },
    tipo_caja_api: null,
    todos_recolectados: false,
    cotizador_enviado: false,
    clasificacion: null,
    resumen_lead: ''
  };
}

const ctx = $('🔧 Preparar Contexto IA').item.json;
const datosAnt = ctx.datosRecolectados || {};
const datosNuevos = result.datos_actualizados || {};

// Clean "desconocido", "null", empty strings → real null
const clean = (v) => (!v || v === 'desconocido' || v === 'null' || v === 'undefined') ? null : v;

const datosMerged = {
  producto: clean(datosNuevos.producto) || clean(datosAnt.producto) || null,
  medidas: clean(datosNuevos.medidas) || clean(datosAnt.medidas) || null,
  fecha: clean(datosNuevos.fecha) || clean(datosAnt.fecha) || null,
  tipo_cajon: clean(datosNuevos.tipo_cajon) || clean(datosAnt.tipo_cajon) || null,
  proteccion_extra: clean(datosNuevos.proteccion_extra) || clean(datosAnt.proteccion_extra) || null,
  direccion: clean(datosNuevos.direccion) || clean(datosAnt.direccion) || null,
  correo_contacto: clean(datosNuevos.correo_contacto) || clean(datosAnt.correo_contacto) || null,
  nombre_cliente: clean(datosNuevos.nombre_cliente) || clean(datosAnt.nombre_cliente) || null
};

// Dimensiones from Groq response
const dims = result.dimensiones || { largo: null, ancho: null, alto: null };

// tipo_caja_api from Groq response
const tipoCajaApi = result.tipo_caja_api || null;

// todos_recolectados — ONLY trust the model. No auto-trigger.
// The model must set this to true only when it has: producto + medidas + tipo_cajón
// Code-level guard: even if model says true, we enforce tipo_cajon must be confirmed
let todosRecolectados = result.todos_recolectados === true;
// Code-level guards: model can't skip required fields
if (todosRecolectados && !clean(datosNuevos.tipo_cajon) && !clean(datosAnt.tipo_cajon)) {
  todosRecolectados = false;
}
// proteccion_extra must be explicitly answered (true or false) — null means it was never asked
const proteccionConfirmada = datosMerged.proteccion_extra !== null && datosMerged.proteccion_extra !== undefined;
if (todosRecolectados && !proteccionConfirmada) {
  todosRecolectados = false;
}

// Valid Airtable Estado options: Nuevo, En calificación, Calificado, Vendedor notificado
let nuevoEstado = ctx.estado;
if (result.cotizador_enviado && result.clasificacion === 'Caliente') nuevoEstado = 'Vendedor notificado';
else if (result.cotizador_enviado) nuevoEstado = 'Calificado';
else if (result.clasificacion === 'Caliente') nuevoEstado = 'Vendedor notificado';
else if (result.clasificacion) nuevoEstado = 'Calificado';
else if (!ctx.leadId || nuevoEstado === 'Nuevo') nuevoEstado = 'En calificación';

const ts = new Date().toISOString();
const nuevoHistorial = (ctx.historial ? ctx.historial + '\n' : '') +
  `[${ts}] Cliente: ${ctx.texto}\n[${ts}] Bot: ${result.mensaje || ''}`;

const mensajeFinal = result.mensaje || '';

return [{ json: {
  ...ctx,
  // Mensaje — ambos nombres para compatibilidad
  mensaje: mensajeFinal,
  mensajeRespuesta: mensajeFinal,
  // Datos recolectados
  datosRecolectados: datosMerged,
  // todos_recolectados — ambos formatos
  todos_recolectados: todosRecolectados,
  todosRecolectados: todosRecolectados,
  // Cotizador
  dimensiones: dims,
  tipo_caja_api: tipoCajaApi,
  cotizador_enviado: result.cotizador_enviado || false,
  cotizadorEnviado: result.cotizador_enviado || false,
  // Lead info
  clasificacion: result.clasificacion || null,
  resumenLead: result.resumen_lead || '',
  nuevoEstado,
  nuevoHistorial
} }];

