const ctx = $('🔧 Preparar Contexto IA').item.json;
const datos = ctx.datosRecolectados || {};
const texto = (ctx.texto || '').trim();
const proximoPaso = ctx.proximoPaso || 'PEDIR_PRODUCTO';

const clean = v => (!v || v === 'desconocido' || v === 'null') ? null : v;

// Try to extract data from current message based on pending step
let datosActualizados = {
  producto: clean(datos.producto) || null,
  medidas: clean(datos.medidas) || null,
  fecha: clean(datos.fecha) || null,
  tipo_cajon: clean(datos.tipo_cajon) || null,
  proteccion_extra: datos.proteccion_extra !== null && datos.proteccion_extra !== undefined ? datos.proteccion_extra : null,
  nombre_cliente: clean(datos.nombre_cliente) || null,
  direccion: clean(datos.direccion) || null
};

// Simple extraction based on current step
if (proximoPaso === 'PEDIR_NOMBRE' && texto) {
  datosActualizados.nombre_cliente = texto;
} else if (proximoPaso === 'PEDIR_PRODUCTO' && texto && !/^(hola|hi|buenas|hey)/i.test(texto)) {
  datosActualizados.producto = texto;
} else if (proximoPaso === 'PEDIR_MEDIDAS' && /\d/.test(texto)) {
  datosActualizados.medidas = texto;
} else if (proximoPaso === 'PEDIR_TIPO_CAJON') {
  // Basic recommendation for contingencia
  const prod = (datosActualizados.producto || '').toLowerCase();
  const tipo = prod.includes('lavadora') || prod.includes('refrigerador') || prod.includes('electrodomestico') || prod.includes('maquina')
    ? 'cajones_cerrados'
    : prod.includes('moto') || prod.includes('bicicleta') ? 'cajones_cerrados'
    : 'cajones_cerrados'; // default to closed crates
  datosActualizados.tipo_cajon = tipo;
} else if (proximoPaso === 'PEDIR_PROTECCION') {
  const acepta = /^(si|sí|yes|dale|claro|ok|quiero|deseo|me gustaria|foam|burbuja|esquinera)/i.test(texto);
  const rechaza = /^(no|nope|sin proteccion|no gracias|no quiero)/i.test(texto);
  if (acepta) datosActualizados.proteccion_extra = true;
  if (rechaza) datosActualizados.proteccion_extra = false;
}

// Determine response based on next step
let mensaje = '';
let todosRecolectados = false;

if (proximoPaso === 'PRIMER_CONTACTO') {
  mensaje = ctx.saludoHora + ', soy Alex, asistente de Crating Express. ¿Con quién tengo el gusto?';
} else if (proximoPaso === 'PEDIR_NOMBRE') {
  mensaje = '¿Con quién tengo el gusto?';
} else if (proximoPaso === 'PEDIR_PRODUCTO') {
  mensaje = ctx.esNuevo
    ? ctx.saludoHora + ', soy Alex, asistente de Crating Express. ¿Con quién tengo el gusto?'
    : '¿Qué artículo necesitas embalar?';
} else if (proximoPaso === 'PEDIR_MEDIDAS') {
  mensaje = '¿Cuáles son las medidas en pulgadas y el peso? (Largo x Alto x Grosor + peso en libras)';
} else if (proximoPaso === 'PEDIR_TIPO_CAJON') {
  const prod = datosActualizados.producto || 'el artículo';
  datosActualizados.tipo_cajon = 'cajones_cerrados';
  mensaje = 'Para ' + prod + ', te recomiendo un cajón cerrado por la protección que ofrece. ¿Te parece bien?';
} else if (proximoPaso === 'PEDIR_PROTECCION') {
  if (datosActualizados.proteccion_extra !== null && datosActualizados.proteccion_extra !== undefined) {
    todosRecolectados = true;
    mensaje = 'Perfecto, preparando tu estimado...';
  } else {
    mensaje = '¿Deseas algún tipo de protección interior como foam, burbuja o esquineras? (tiene costo adicional)';
  }
} else if (proximoPaso === 'LISTO_PARA_COTIZAR') {
  todosRecolectados = true;
  mensaje = 'Perfecto, preparando tu estimado para ' + (datosActualizados.producto || 'el artículo') + ':';
} else {
  mensaje = '¿En qué puedo ayudarte?';
}

return [{ json: {
  mensaje,
  datos_actualizados: datosActualizados,
  dimensiones: { largo: null, ancho: null, alto: null },
  tipo_caja_api: datosActualizados.tipo_cajon === 'cajones_cerrados' ? 'cajones_cerrados' : null,
  todos_recolectados: todosRecolectados,
  cotizador_enviado: false,
  clasificacion: null,
  resumen_lead: todosRecolectados ? ('Contingencia — ' + (datosActualizados.producto || '')) : '',
  _contingencia: true
} }];

